lab.solution:
records = [{'track': 'Python', 'minutes': 20}, {'track': 'Python', 'minutes': 15}]
totals = {}
for row in records:
    track = row['track']
    minutes = row['minutes']
    if minutes is None:
        raise ValueError('minutes is required')
    totals[track] = totals.get(track, 0) + minutes
print(totals)
